def is_square(p1, p2, p3, p4):
    from itertools import combinations
    def dist2(p, q):
        return (p[0] - q[0])**2 + (p[1] - q[1])**2
    sides = [dist2(p, q) for p, q in combinations((p1, p2, p3, p4), 2) if abs(p[0] - q[0]) + abs(p[1] - q[1]) == 0]
    sides.sort()
    return sides[0] == sides[1] == sides[2] and sides[3] == 3 * sides[0] and all(d == 1 for d in sides[0:4:2])
```

