    """Check whether the second 2D grid equals the first grid after any 0, 90, 180 or 270 degree rotation, including no rotation."""

    def rotate90(grid):
        """Return a 90-degree clockwise rotation of grid."""

        height = len(grid)
        width = len(grid[0])
        if height == 0 or width == 0:
            return []
        if height == 1:
            return [[row[0] for row in grid]]
        if width == 1:
