def parse_url_parts(url: str) -> Dict[str, str]:
    match = re.fullmatch(r'([a-zA-Z0-9+.-]+)://([^/?]+)(/[^?]*)(\?[^#]*)?', url)
    if not match:
        return {
            'scheme': '',
            'host': '',
            'path': '',
            'query': ''
        }
    groups = match.groups()
    scheme, host, path, query = groups or ('', '', '', '')  # default empty strings for optional capture groups
